actions.script:
if (!ec.user.isInGroup('ADMIN') && !ec.user.isInGroup('ZENITH_ADMIN'))
    throw new org.moqui.context.ArtifactAuthorizationException('Only an administrator can change terminal assignments.')
if (organizationPartyId != ec.user.getPreference('ACTIVE_ORGANIZATION'))
    throw new org.moqui.context.ArtifactAuthorizationException('Switch to the assignment organization before changing it.')
def terminal=terminalId ? ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',terminalId).disableAuthz().one() : null
if (terminal && terminal.organizationPartyId != organizationPartyId)
    throw new org.moqui.context.ArtifactAuthorizationException('The assigned terminal must belong to this organization.')
